```bash
cd /home/vscode/nullness-benchmarks/glide && sed -i '24a\ \ \ private static final InputStream EMPTY = new InputStream() {
\ \ \ \ @Override
\ \ \ \ public int read() {
\ \ \ \ \ \ return -1;
\ \ \ \ }
\ \ \ };' library/src/main/java/com/bumptech/glide/util/ExceptionCatchingInputStream.java && sed -i '135,138s/wrapped = null;/wrapped = EMPTY;/' library/src/main/java/com/bumptech/glide/util/ExceptionCatchingInputStream.java && ./gradlew library:compileDebugJavaWithJavac -x test -q > new_build_output.log 2>&1```

